import { StyleSheet } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

/**
 * Creates all list styles derived from the active theme.
 * @param t - The resolved PdfcnTheme instance.
 */
export const createListStyles = (t: PdfcnTheme) => {
  const { borderRadius, spacing, fontWeights, typography } = t.primitives;

  return StyleSheet.create({
    checkBox: {
      alignItems: "center",
      backgroundColor: t.colors.background,
      borderColor: t.colors.border,
      borderRadius: 3,
      borderStyle: "solid",
      borderWidth: 1.5,
      height: spacing[4],
      justifyContent: "center",
      marginRight: spacing[2],
      width: spacing[4],
    },
    checkBoxChecked: {
      backgroundColor: t.colors.success,
      borderColor: t.colors.success,
    },
    checklistTextWrap: {
      flex: 1,
      marginLeft: spacing[2],
    },
    childrenContainer: {
      display: "flex",
      flexDirection: "column",
      marginLeft: spacing[5],
      marginTop: spacing[1],
    },
    container: {
      display: "flex",
      flexDirection: "column",
      marginBottom: t.spacing.componentGap,
      width: "100%",
    },
    descriptiveAccent: {
      backgroundColor: t.colors.primary,
      borderRadius: borderRadius.sm,
      marginRight: spacing[3],
      minHeight: spacing[4],
      width: 3,
    },
    descriptiveContent: {
      flex: 1,
    },
    descriptiveDesc: {
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.sm,
      lineHeight: t.typography.body.lineHeight,
      marginTop: 1,
    },
    descriptiveTitle: {
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      fontWeight: fontWeights.semibold,
      lineHeight: t.typography.body.lineHeight,
    },
    iconBox: {
      alignItems: "center",
      backgroundColor: t.colors.primary,
      borderRadius: borderRadius.md,
      height: spacing[5],
      justifyContent: "center",
      marginRight: spacing[2],
      width: spacing[5],
    },
    iconMark: {
      color: t.colors.primaryForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: 9,
      fontWeight: fontWeights.bold,
    },
    itemRow: {
      alignItems: "flex-start",
      flexDirection: "row",
    },
    itemRowCenter: {
      alignItems: "center",
      flexDirection: "row",
    },
    itemRowGapMd: { marginBottom: spacing[3] },
    itemRowGapSm: { marginBottom: spacing[2] },
    itemRowGapXs: { marginBottom: spacing[1] },
    itemText: {
      // No flex here — Text nodes with flex shorthand get flexBasis:0, which causes
      // Yoga to under-measure multi-line text height → overlapping rows.
      // flex:1 must live on the wrapping View, not on the Text itself.
      color: t.colors.foreground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize,
      lineHeight: t.typography.body.lineHeight,
    },
    itemTextBold: {
      fontWeight: fontWeights.semibold,
    },
    itemTextSub: {
      // Same: no flex — see itemText comment.
      color: t.colors.mutedForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: t.typography.body.fontSize - 0.5,
      lineHeight: t.typography.body.lineHeight,
    },
    itemTextWrap: {
      // Companion to itemText / itemTextSub. Apply this to the View that wraps
      // the Text so flex expansion happens at the View level, not the Text level.
      flex: 1,
    },
    markerBulletDot: {
      backgroundColor: t.colors.primary,
      borderRadius: 3,
      height: 5,
      width: 5,
    },
    markerBulletSubDot: {
      backgroundColor: "transparent",
      borderColor: t.colors.mutedForeground,
      borderRadius: 2,
      borderStyle: "solid",
      borderWidth: 1,
      height: 4,
      width: 4,
    },
    markerBulletSubWrap: {
      alignItems: "center",
      justifyContent: "flex-start",
      marginTop: spacing[1],
      width: spacing[4],
    },
    markerBulletWrap: {
      alignItems: "center",
      justifyContent: "flex-start",
      marginTop: spacing[1],
      width: spacing[4],
    },
    markerNumberBadge: {
      alignItems: "center",
      backgroundColor: t.colors.primary,
      borderRadius: spacing[5],
      height: spacing[5],
      justifyContent: "center",
      marginRight: spacing[2],
      width: spacing[5],
    },
    markerNumberText: {
      color: t.colors.primaryForeground,
      fontFamily: t.typography.body.fontFamily,
      fontSize: typography.xs,
      fontWeight: fontWeights.bold,
    },
  });
};

import { NgTemplateOutlet } from "@angular/common";
import { booleanAttribute, Component, computed, input } from "@angular/core";

import { injectPdfcnTheme } from "@/components/pdf/theme-provider";
import {
  FormeText,
  FormeView,
} from "@/lib/pdf-primitives";
import type { Style } from "@/lib/pdf-primitives";
import type { PdfcnTheme } from "@/types/pdf-themes";

import { createListStyles } from "./list.styles";
import type { ListItem, ListVariant, PdfListProps } from "./list.types";

type Styles = ReturnType<typeof createListStyles>;
type GapProp = "xs" | "sm" | "md";

/** One rendered row. Bullet and multi-level rows carry a marker and nested rows. */
interface ListRow {
  variant: ListVariant;
  item: ListItem;
  rowStyle: Style[];
  label?: string;
  boxStyle?: Style[];
  marker?: { wrap: Style; dot: Style };
  textStyle?: Style[];
  children?: { style: Style | undefined; rows: (ListRow | null)[] } | null;
}

const getGapStyle = (gap: GapProp, styles: Styles): Style => {
  if (gap === "xs") {
    return styles.itemRowGapXs;
  }
  if (gap === "md") {
    return styles.itemRowGapMd;
  }
  return styles.itemRowGapSm;
};

const buildRowStyles = (
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles,
  align: "start" | "center" = "start"
): Style[] => {
  const row: Style[] = [
    align === "center" ? styles.itemRowCenter : styles.itemRow,
  ];
  if (index !== total - 1) {
    row.push(getGapStyle(gap, styles));
  }
  return row;
};

/** Bullet dot marker — solid filled for level 0, outline ring for nested levels. */
const dotMarker = (level: number, styles: Styles) =>
  level === 0
    ? { dot: styles.markerBulletDot, wrap: styles.markerBulletWrap }
    : { dot: styles.markerBulletSubDot, wrap: styles.markerBulletSubWrap };

// eslint-disable-next-line no-use-before-define, prefer-const
let renderBulletItem: (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles,
  level: number
) => ListRow;
// eslint-disable-next-line no-use-before-define, prefer-const
let renderMultiLevelItem: (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles,
  level: number
) => ListRow;

const renderNumberedItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): ListRow => ({
  item,
  label: `${index + 1}`,
  rowStyle: buildRowStyles(index, total, gap, styles, "center"),
  variant: "numbered",
});

const renderChecklistItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): ListRow => {
  const isChecked = item.checked ?? true;
  return {
    boxStyle: [styles.checkBox, isChecked ? styles.checkBoxChecked : {}],
    item,
    rowStyle: buildRowStyles(index, total, gap, styles, "center"),
    variant: "checklist",
  };
};

const renderIconItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): ListRow => ({
  item,
  rowStyle: buildRowStyles(index, total, gap, styles, "center"),
  variant: "icon",
});

const renderDescriptiveItem = (
  item: ListItem,
  index: number,
  total: number,
  gap: GapProp,
  styles: Styles
): ListRow => ({
  item,
  rowStyle: buildRowStyles(index, total, gap, styles),
  variant: "descriptive",
});

const renderItem = (
  item: ListItem,
  index: number,
  total: number,
  variant: ListVariant,
  gap: GapProp,
  styles: Styles,
  level: number
): ListRow | null => {
  switch (variant) {
    case "bullet": {
      return renderBulletItem(item, index, total, gap, styles, level);
    }
    case "numbered": {
      return renderNumberedItem(item, index, total, gap, styles);
    }
    case "checklist": {
      return renderChecklistItem(item, index, total, gap, styles);
    }
    case "icon": {
      return renderIconItem(item, index, total, gap, styles);
    }
    case "multi-level": {
      return renderMultiLevelItem(item, index, total, gap, styles, level);
    }
    case "descriptive": {
      return renderDescriptiveItem(item, index, total, gap, styles);
    }
    default: {
      break;
    }
  }
  return null;
};

const renderItemList = (
  items: ListItem[],
  variant: ListVariant,
  gap: GapProp,
  styles: Styles,
  level: number
) => ({
  rows: items.map((item, index) =>
    renderItem(item, index, items.length, variant, gap, styles, level)
  ),
  style: level > 0 ? styles.childrenContainer : undefined,
});

renderBulletItem = (item, index, total, gap, styles, level) => ({
  children:
    item.children && item.children.length > 0
      ? renderItemList(item.children, "bullet", gap, styles, level + 1)
      : null,
  item,
  marker: dotMarker(level, styles),
  rowStyle: buildRowStyles(index, total, gap, styles),
  textStyle: [styles.itemText],
  variant: "bullet",
});

renderMultiLevelItem = (item, index, total, gap, styles, level) => ({
  children:
    item.children && item.children.length > 0
      ? renderItemList(item.children, "multi-level", gap, styles, level + 1)
      : null,
  item,
  marker: dotMarker(level, styles),
  rowStyle: buildRowStyles(index, total, gap, styles),
  textStyle: [
    level === 0 ? styles.itemText : styles.itemTextSub,
    level === 0 ? styles.itemTextBold : {},
  ],
  variant: "multi-level",
});

const listLayout = (
  theme: PdfcnTheme,
  { items, variant = "bullet", gap = "sm", style, _level = 0 }: PdfListProps
) => {
  const styles = createListStyles(theme);

  const containerStyles: Style[] = [styles.container];
  if (_level > 0) {
    containerStyles.push(styles.childrenContainer);
  }
  const styleArray = style ? [...containerStyles, style] : containerStyles;

  return {
    container: styleArray,
    rows: items.map((item, index) =>
      renderItem(item, index, items.length, variant, gap, styles, _level)
    ),
    styles,
  };
};

/** List of items with multiple style variants including bullet, numbered, checklist, and descriptive. */
@Component({
  imports: [FormeText, FormeView, NgTemplateOutlet],
  selector: "pdf-list",
  template: `
    @let s = layout().styles;
    <forme-view [style]="layout().container">
      <ng-container
        *ngTemplateOutlet="rowList; context: { $implicit: layout().rows }"
      />
    </forme-view>
    <ng-template #rowList let-rows>
      @for (row of asRows(rows); track $index) {
        @if (row) {
          @switch (row.variant) {
            @case ("numbered") {
              <forme-view [style]="row.rowStyle">
                <forme-view [style]="s.markerNumberBadge">
                  <forme-text [style]="s.markerNumberText">{{
                    row.label
                  }}</forme-text>
                </forme-view>
                <forme-view [style]="s.itemTextWrap">
                  <forme-text [style]="s.itemText">{{
                    row.item.text
                  }}</forme-text>
                </forme-view>
              </forme-view>
            }
            @case ("checklist") {
              <forme-view [style]="row.rowStyle">
                <forme-view [style]="row.boxStyle" />
                <forme-view [style]="s.checklistTextWrap">
                  <forme-text [style]="s.itemText">{{
                    row.item.text
                  }}</forme-text>
                </forme-view>
              </forme-view>
            }
            @case ("icon") {
              <forme-view [style]="row.rowStyle">
                <forme-view [style]="s.iconBox">
                  <forme-text [style]="s.iconMark">★</forme-text>
                </forme-view>
                <forme-view [style]="s.itemTextWrap">
                  <forme-text [style]="s.itemText">{{
                    row.item.text
                  }}</forme-text>
                </forme-view>
              </forme-view>
            }
            @case ("descriptive") {
              <forme-view [style]="row.rowStyle">
                <forme-view [style]="s.descriptiveAccent" />
                <forme-view [style]="s.descriptiveContent">
                  <forme-text [style]="s.descriptiveTitle">{{
                    row.item.text
                  }}</forme-text>
                  @if (row.item.description) {
                    <forme-text [style]="s.descriptiveDesc">{{
                      row.item.description
                    }}</forme-text>
                  }
                </forme-view>
              </forme-view>
            }
            @default {
              <forme-view>
                <forme-view [style]="row.rowStyle">
                  <forme-view [style]="row.marker?.wrap">
                    <forme-view [style]="row.marker?.dot" />
                  </forme-view>
                  <forme-view [style]="s.itemTextWrap">
                    <forme-text [style]="row.textStyle">{{
                      row.item.text
                    }}</forme-text>
                  </forme-view>
                </forme-view>
                @if (row.children) {
                  <forme-view [style]="row.children.style">
                    <ng-container
                      *ngTemplateOutlet="
                        rowList;
                        context: { $implicit: row.children.rows }
                      "
                    />
                  </forme-view>
                }
              </forme-view>
            }
          }
        }
      }
    </ng-template>
  `,
})
export class PdfList {
  readonly items = input.required<ListItem[]>();
  readonly variant = input<ListVariant>("bullet");
  readonly gap = input<GapProp>("sm");
  /** Part of the props API but unused, as in the original. */
  readonly noWrap = input(false, { transform: booleanAttribute });
  readonly style = input<PdfListProps["style"]>();
  readonly _level = input(0);

  private readonly theme = injectPdfcnTheme();
  protected readonly layout = computed(() =>
    listLayout(this.theme(), {
      _level: this._level(),
      gap: this.gap(),
      items: this.items(),
      style: this.style(),
      variant: this.variant(),
    })
  );

  protected readonly asRows = (rows: (ListRow | null)[]) => rows;
}

import type { Style } from "@/lib/pdf-primitives";

/** List visual style variant. */
export type ListVariant =
  | "bullet"
  | "numbered"
  | "checklist"
  | "icon"
  | "multi-level"
  | "descriptive";

/**
 * A single list item, optionally with nested children.
 * Props - `text` | `description` | `checked` | `children`
 * @see {@link ListItem}
 */
export interface ListItem {
  text: string;
  description?: string;
  checked?: boolean;
  children?: ListItem[];
}

/**
 * List of items with multiple style variants including bullet, numbered, checklist, and descriptive.
 * Props - `items` | `variant` | `gap` | `style` | `_level` | `noWrap`
 * @see {@link PdfListProps}
 */
export interface PdfListProps {
  items: ListItem[];
  /**
   * @default 'bullet'
   */
  variant?: ListVariant;
  /**
   * @default 'sm'
   */
  gap?: "xs" | "sm" | "md";
  style?: Style;
  _level?: number;
  /**
   * @default false
   */
  noWrap?: boolean;
}
